const SUPER_PRICE_CATEGORIES = new Set([2, 3, 6, 11, 19]);
const BOGO_CATEGORIES = new Set([15, 16]);

export const FALLBACK_PRODUCT_ROWS: CatalogRow[] = SAMPLES.map(([cat, name, size, price, sub], i) => {
  const rootId = `demo-${String(cat).padStart(2, "0")}`;
  const subId = sub >= 0 ? `${rootId}-${sub}` : null;
  const firstOfCategory = i === 0 || SAMPLES[i - 1][0] !== cat;
  const perKg = size === "ανά κιλό";
  return {
    id: `demo-p${String(i).padStart(2, "0")}`,
    name,
    description: null,
    size: perKg ? null : size,
    image_url: `/kaimakidis/categories/${String(cat).padStart(2, "0")}.webp`,
    price,
    price_unit: perKg ? "kg" : "piece",
    is_super_price: firstOfCategory && SUPER_PRICE_CATEGORIES.has(cat),
    is_bogo: firstOfCategory && BOGO_CATEGORIES.has(cat),
    barcode: null,
    category_id: subId ?? rootId,
    root_category_id: rootId,
    subcategory_id: subId,
    updated_at: "2026-10-20T00:00:00Z",
  };
});

